function onChange(control, oldValue, newValue, isLoading, isTemplate) {
   if (isLoading || newValue === '') {
      return;
   }

   var prc=g_form.getValue("project_category");
   var status=g_form.getValue('status');
   alert("status"+status);
   if(status=='e4dfba35536ed210f91579a0a0490e49'&&(prc=='0ed1c775536ed210f91579a0a0490ee5')||(prc=='bae10775536ed210f91579a0a0490e02')||(prc=='11f10339536ed210f91579a0a0490e86')||(prc=='ad020739536ed210f91579a0a0490e41')||(prc=='5c128fb5536ed210f91579a0a0490e86')){
   /* e4dfba35536ed210f91579a0a0490e49-Awaiting Prioritization
   0ed1c775536ed210f91579a0a0490ee5-Existing Project
   bae10775536ed210f91579a0a0490e02-Client PoC
   11f10339536ed210f91579a0a0490e86-Learnings
   ad020739536ed210f91579a0a0490e41-R&D 
   5c128fb5536ed210f91579a0a0490e86-Others*/
   //dfc1cf75536ed210f91579a0a0490ee9-New Idea



	g_form.setMandatory('project_manager',true);
	g_form.setMandatory('technical_lead',true);
	g_form.setMandatory('project_owner',true);

   }
   else{
	g_form.setMandatory('project_manager',false);
	g_form.setMandatory('technical_lead',false);
	g_form.setMandatory('project_owner',false);

   }


}   //Type appropriate comment here, and begin script below
